using System.Collections.ObjectModel;using Microsoft.Extensions.DependencyInjection;using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using UPM.Windows.Core;using UPM.Windows.SiteApi;
namespace UPM.SiteManager.Views;
public sealed partial class TransfersPage:Page{private readonly LocalStateStore store=App.Services.GetRequiredService<LocalStateStore>();private readonly IOperatorContext context=App.Services.GetRequiredService<IOperatorContext>();private readonly ObservableCollection<TransferRow> rows=[];private bool subscribed;public TransfersPage(){InitializeComponent();TransferList.ItemsSource=rows;}private void OnLoaded(object s,RoutedEventArgs e){if(!subscribed){context.Changed+=OnChanged;subscribed=true;}_=RefreshAsync();}private void OnUnloaded(object s,RoutedEventArgs e){if(subscribed){context.Changed-=OnChanged;subscribed=false;}}private void OnChanged(object? s,OperatorContextChangedEventArgs e)=>DispatcherQueue.TryEnqueue(()=>_=RefreshAsync());private void OnRefresh(object s,RoutedEventArgs e)=>_=RefreshAsync();private async Task RefreshAsync(){try{var profiles=(await store.ListSiteProfilesAsync()).ToDictionary(x=>x.ProfileId);var transfers=await store.ListTransfersAsync();rows.Clear();foreach(var x in transfers){var percent=x.Length>0?Math.Clamp(100d*x.BytesTransferred/x.Length,0,100):0;rows.Add(new TransferRow{Filename=x.OriginalFilename,RelativePath=x.RelativePath,Profile=profiles.TryGetValue(x.SiteProfileId,out var p)?p.DisplayName:x.SiteProfileId.ToString(),Event=x.EventId?.ToString()??"No event",State=x.State.ToString().ToUpperInvariant(),Progress=$"{JsonProjection.Bytes(x.BytesTransferred)} / {JsonProjection.Bytes(x.Length)}",Percent=percent,Retry=$"Retries: {x.RetryCount}",Error=x.Error??""});}Totals.Text=$"ACTIVE {transfers.Count(x=>x.State is TransferState.Hashing or TransferState.Uploading or TransferState.Verifying)}  •  QUEUED {transfers.Count(x=>x.State==TransferState.Queued)}  •  COMPLETE {transfers.Count(x=>x.State==TransferState.Complete)}  •  FAILED {transfers.Count(x=>x.State==TransferState.Failed)}";if(rows.Count==0){StateBar.Title="TRANSFERS";StateBar.Message="No transfer activity. Accepted transfers persist across restarts.";StateBar.Severity=InfoBarSeverity.Informational;StateBar.IsOpen=true;}else StateBar.IsOpen=false;}catch(Exception ex){StateBar.Title="LOCAL QUEUE ERROR";StateBar.Message=ex.Message;StateBar.Severity=InfoBarSeverity.Error;StateBar.IsOpen=true;}}}
public sealed class TransferRow{public string Filename{get;set;}="";public string RelativePath{get;set;}="";public string Profile{get;set;}="";public string Event{get;set;}="";public string State{get;set;}="";public string Progress{get;set;}="";public double Percent{get;set;}public string Retry{get;set;}="";public string Error{get;set;}="";}
